// 描画を軽くするため、面積が約13km^2未満の島と小笠原諸島は省いています。

export type PrefectureShape = {
  id: number;
  name: string;
  /** SVGのpath要素に渡す形状データ */
  d: string;
};

export const JAPAN_MAP_WIDTH = 479.3;
export const JAPAN_MAP_HEIGHT = 485.1;

/** 南西諸島（沖縄・奄美）をまとめて表示する枠の位置 */
export const JAPAN_MAP_INSET_BOX = {
  x: 268.8,
  y: 346.1,
  width: 206.5,
  height: 135.0
};

// 緯度経度を地図上の位置に変換するための定数（メルカトル図法）
const LON_SCALE = 24.82768991;
const LON_OFFSET = -3006.57008664;
const LAT_OFFSET = 1182.96301078;
const LAT_SCALE = 1304.85361931;
const VIEW_X0 = 178.20182502;
const VIEW_Y0 = -0.65718183;
// 南西諸島を別枠へ移すための境界と変換
const INSET_MAX_X = 270.68498136;
const INSET_MIN_Y = 479.31462385;
const INSET_SCALE = 0.85;
const INSET_DX = 442.95118667;
const INSET_DY = -55.95375237;

/**
 * 緯度経度を地図上の座標(x, y)に変換する。
 * 沖縄・奄美は右下の別枠内に配置される。
 * 日本の範囲外の座標は null を返す。
 */
export function projectToJapanMap(
  lat: number,
  lng: number
): { x: number; y: number } | null {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
    return null;
  }

  let x = LON_SCALE * lng + LON_OFFSET;
  let y = LAT_OFFSET - LAT_SCALE * Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360));

  if (y > INSET_MIN_Y && x < INSET_MAX_X) {
    x = x * INSET_SCALE + INSET_DX;
    y = y * INSET_SCALE + INSET_DY;
  }

  const mapX = x - VIEW_X0;
  const mapY = y - VIEW_Y0;

  if (mapX < 0 || mapY < 0 || mapX > JAPAN_MAP_WIDTH || mapY > JAPAN_MAP_HEIGHT) {
    return null;
  }

  return { x: mapX, y: mapY };
}

